import json
import sys
import time
from datetime import datetime, timedelta

def load_config(config_path):
    with open(config_path) as f:
        return json.load(f)

def generate_token(name, role, secret):
    timestamp = datetime.utcnow().isoformat() + 'Z'
    return f"{name}:{role}:{timestamp}:{secret}"

def validate_token(token, secret, role):
    parts = token.split(':')
    if len(parts) != 4:
        return False
    name, token_role, timestamp_str, issued_secret = parts
    try:
        timestamp = datetime.fromisoformat(timestamp_str)
    except ValueError:
        return False
    if issued_secret != secret:
        return False
    if datetime.utcnow() - timestamp > timedelta(minutes=15):
        return False
    return token_role == role

def process_issue(api_key, config, secret):
    if api_key not in config['clients']:
        return "DENY"
    client = config['clients'][api_key]
    token = generate_token(client['name'], client['role'], secret)
    return token

def process_check(token, role, secret):
    if validate_token(token, secret, role):
        return "ALLOW"
    return "DENY"

def log_deny(command, identifier):
    timestamp = datetime.utcnow().isoformat() + 'Z'
    with open('auth.log', 'a') as f:
        f.write(f"{timestamp} {command} {identifier}\n")

def main():
    if len(sys.argv) != 2:
        sys.stderr.write("Usage: python token_cli.py <config_path>\n")
        sys.exit(1)

    config = load_config(sys.argv[1])
    secret = config['secret']

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        parts = line.split()
        if len(parts) < 2:
            sys.stderr.write("ERROR\n")
            continue

        command = parts[0]
        if command not in ('issue', 'check'):
            sys.stderr.write("ERROR\n")
            continue

        if command == 'issue':
            if len(parts) != 2:
                sys.stderr.write("ERROR\n")
                continue
            api_key = parts[1]
            result = process_issue(api_key, config, secret)
            if result == "DENY":
                log_deny('issue', api_key)
            print(result)
        elif command == 'check':
            if len(parts) != 3:
                sys.stderr.write("ERROR\n")
                continue
            token = parts[1]
            role = parts[2]
            result = process_check(token, role, secret)
            if result == "DENY":
                log_deny('check', role)
            print(result)

if __name__ == "__main__":
