import json
import sys
import time
from datetime import datetime, timedelta

class TokenManager:
    def __init__(self, config_path):
        with open(config_path) as f:
            self.config = json.load(f)
        self.secret = self.config["secret"]
        self.clients = self.config["clients"]
        self.log_file = "auth.log"

    def issue_token(self, api_key):
        if api_key not in self.clients:
            return "DENY"
        role = self.clients[api_key]
        token = f"{role}|{self.secret}|{datetime.utcnow().isoformat()}"
        return token

    def validate_token(self, token, role):
        parts = token.split("|")
        if len(parts) != 3:
            return False
        stored_secret, stored_role, issued_time_str = parts
        issued_time = datetime.fromisoformat(issued_time_str.replace('Z', '+00:00'))
        current_time = datetime.utcnow()
        if stored_secret != self.secret or stored_role != role or (current_time - issued_time) > timedelta(minutes=15):
            return False
        return True

def process_command(config_manager, command_line):
    parts = command_line.strip().split()
    if not parts:
        return "ERROR", None
    if parts[0] == "issue":
        if len(parts) != 2:
            return "ERROR", None
        api_key = parts[1]
        token = config_manager.issue_token(api_key)
        return None, token
    elif parts[0] == "check":
        if len(parts) != 3:
            return "ERROR", None
        token, role = parts[1], parts[2]
        is_valid = config_manager.validate_token(token, role)
        return "ALLOW" if is_valid else "DENY", None
    else:
        return "ERROR", None

def log_deny(command_type, identifier):
    timestamp = datetime.utcnow().isoformat() + "Z"
    with open(config_manager.log_file, "a") as f:
        f.write(f"{timestamp} {command_type} {identifier}\n")

def main():
    if len(sys.argv) != 2:
        sys.stderr.write("Usage: python token_cli.py <config_path>\n")
        return
    config_manager = TokenManager(sys.argv[1])
    for line in sys.stdin:
        line = line.strip()
        result, token = process_command(config_manager, line)
        if result == "ERROR":
            sys.stderr.write("ERROR\n")
        elif result == "DENY":
            log_deny("issue" if token is None else "check", token.split("|")[-1] if token else line.split()[2])
            sys.stdout.write("DENY\n")
        else:
            sys.stdout.write(result + "\n")

if __name__ == "__main__":
    main()

import json
import sys
import time
from datetime import datetime
from typing import Dict, Optional

def main():
    if len(sys.argv) != 2:
        sys.stderr.write("Usage: python token_cli.py <config_path>\n")
        sys.exit(1)

    config_path = sys.argv[1]
    try:
        with open(config_path, 'r') as f:
            config = json.load(f)
    except Exception as e:
        sys.stderr.write(f"Error reading config: {e}\n")
        sys.exit(1)

    if "secret" not in config or "clients" not in config:
        sys.stderr.write("Invalid config format\n")
        sys.exit(1)

    current_secret = config["secret"]
    clients = config["clients"]
    issued_tokens: Dict[str, Dict[str, str]] = {}

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        parts = line.split()
        if len(parts) < 2:
            sys.stderr.write("ERROR\n")
            continue

        command = parts[0]
        if command not in ("issue", "check"):
            sys.stderr.write("ERROR\n")
            continue

        if command == "issue":
            if len(parts) != 2:
                sys.stderr.write("ERROR\n")
                continue
            api_key = parts[1]
            if api_key not in clients:
                print("DENY")
                log_entry(api_key, "issue")
            else:
                role = clients[api_key]
                token = f"token_{current_secret}_{role}_{int(time.time())}"
                issued_tokens[token] = {"role": role, "secret": current_secret}
                print(token)

        elif command == "check":
            if len(parts) != 3:
                sys.stderr.write("ERROR\n")
                continue
            token, role = parts[1], parts[2]
            if token not in issued_tokens:
                print("DENY")
                log_entry(role, "check")
            else:
                token_data = issued_tokens[token]
                if token_data["secret"] == current_secret and token_data["role"] == role:
                    print("ALLOW")
                else:
                    print("DENY")
                    log_entry(role, "check")

def log_entry(identifier: str, command: str):
    timestamp = datetime.utcnow().isoformat() + "Z"
    log_entry = f"{timestamp} {command} {identifier}\n"
    with open("auth.log", "a") as f:
        f.write(log_entry)

if __name__ == "__main__":
    main()
